public/archive.css.text:
/* Shared ARG interface. Keep independent of each fictional site's theme. */
#archiveButton {
  display:inline-flex; align-items:center; justify-content:center; flex:0 0 auto;
  min-width:88px; min-height:44px; height:auto; width:auto; margin-left:auto;
  padding:9px 14px; border:1px solid #b8b8b8; border-radius:4px;
  background:#fff; color:#333; box-shadow:none; text-decoration:none;
  font:500 14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans JP","Yu Gothic",sans-serif;
  letter-spacing:normal; white-space:nowrap; cursor:pointer; box-sizing:border-box;
}
#archiveButton:hover { background:#f1f1f1; border-color:#888; color:#222; }
#archiveButton:focus-visible { outline:2px solid #555; outline-offset:3px; }
#archiveOverlay {
  position:fixed; inset:0; z-index:10000; display:none; place-items:center;
  padding:24px; margin:0; background:rgba(0,0,0,.5); opacity:0; visibility:hidden;
  color:#262626; text-align:left; letter-spacing:normal; transition:none;
  font:400 16px/1.8 -apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans JP","Yu Gothic",sans-serif;
}
#archiveOverlay.is-open { display:grid; opacity:1; visibility:visible; }
#archiveOverlay, #archiveOverlay * { box-sizing:border-box; }
#archiveOverlay .archive-dialog {
  display:flex; flex-direction:column; width:min(640px,100%); min-width:0;
  max-width:100%; max-height:calc(100vh - 48px); max-height:calc(100dvh - 48px);
  margin:0; padding:0; overflow:hidden; border:1px solid #d2d2d2; border-radius:6px;
  background:#fff; color:#262626; box-shadow:0 16px 48px rgba(0,0,0,.22);
  transform:none; transition:none; font:inherit; letter-spacing:normal;
}
#archiveOverlay .archive-header {
  display:flex; flex:0 0 auto; align-items:center; justify-content:space-between;
  gap:16px; margin:0; padding:18px 20px; border:0; border-bottom:1px solid #ddd;
  background:#fafafa; color:#262626;
}
#archiveOverlay .archive-header h2 {
  margin:0; padding:0; color:#262626;
  font-family:inherit; font-size:20px; font-weight:600; line-height:1.5; letter-spacing:normal;
}
#archiveOverlay .archive-close {
  display:inline-flex; align-items:center; justify-content:center; flex:0 0 40px;
  width:40px; height:40px; min-height:40px; margin:0; padding:0;
  border:1px solid #ccc; border-radius:4px; background:#fff; color:#333;
  font-family:inherit; font-weight:400; font-size:25px; line-height:1;
  cursor:pointer; box-shadow:none;
}
#archiveOverlay .archive-content {
  flex:1 1 auto; min-height:0; max-height:none; margin:0; padding:20px;
  overflow:auto; overscroll-behavior:contain; background:#fff; color:#262626;
}
#archiveOverlay .archive-description {
  margin:0 0 20px; padding:0; color:#505050; font:inherit;
  font-size:16px; font-weight:400; line-height:1.85; letter-spacing:normal;
}
#archiveOverlay .archive-list {
  display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px;
  max-height:none; margin:0; padding:0; overflow:visible; list-style:none;
  border:0; background:transparent; color:#262626;
}
#archiveOverlay .archive-list li { min-width:0; margin:0; padding:0; border:0; list-style:none; }
#archiveOverlay .archive-entry {
  display:flex; align-items:flex-start; gap:10px; height:100%; min-width:0;
  margin:0; padding:12px; border:1px solid #ddd; border-radius:4px;
  background:#fff; color:#262626; text-decoration:none; box-shadow:none;
  font:inherit; font-size:15px; font-weight:400; line-height:1.7; letter-spacing:normal;
  transform:none; transition:none;
}
#archiveOverlay a.archive-entry:hover { background:#eee; color:#222; border-color:#aaa; }
#archiveOverlay .archive-entry.is-locked { background:#f5f5f5; color:#858585; cursor:default; user-select:none; }
#archiveOverlay .archive-number {
  flex:0 0 25px; margin:0; color:inherit; font:500 15px/1.7 Consolas,monospace;
  letter-spacing:normal;
}
#archiveOverlay .archive-title { min-width:0; color:inherit; font:inherit; letter-spacing:normal; overflow-wrap:anywhere; white-space:normal; }
#archiveOverlay .archive-entry.is-locked .archive-number,
#archiveOverlay .archive-entry.is-locked .archive-title { color:#858585; letter-spacing:normal; }
#archiveOverlay .archive-tools { display:block; margin:20px 0 0; padding:20px 0 0; border:0; border-top:1px solid #ddd; }
#archiveOverlay .archive-reset-button,
#archiveOverlay .reset-actions button {
  min-height:44px; margin:0; padding:9px 14px; border:1px solid #bbb; border-radius:4px;
  background:#fff; color:#333; box-shadow:none; cursor:pointer;
  font:inherit; font-size:14px; line-height:1.6; letter-spacing:normal;
}
#archiveOverlay button:hover { background:#eee; color:#222; border-color:#888; }
#archiveOverlay a:focus-visible, #archiveOverlay button:focus-visible { outline:2px solid #555; outline-offset:2px; }
#archiveOverlay .reset-confirm { margin:16px 0 0; padding:16px; border:1px solid #d0d0d0; border-radius:4px; background:#f6f6f6; color:#333; font:inherit; }
#archiveOverlay .reset-confirm[hidden] { display:none; }
#archiveOverlay .reset-confirm p { margin:0 0 14px; color:#333; font:inherit; font-size:16px; }
#archiveOverlay .reset-actions { display:flex; flex-wrap:wrap; justify-content:flex-end; gap:10px; margin:0; padding:0; }
#archiveOverlay .reset-actions .danger { background:#444; color:#fff; border-color:#444; }
#archiveOverlay .reset-actions .danger:hover { background:#222; color:#fff; border-color:#222; }
@media(max-width:600px) {
  #archiveOverlay { padding:12px; }
  #archiveOverlay .archive-dialog { max-height:calc(100vh - 24px); max-height:calc(100dvh - 24px); }
  #archiveOverlay .archive-header { padding:14px 16px; }
  #archiveOverlay .archive-content { padding:16px; }
  #archiveOverlay .archive-list { grid-template-columns:1fr; }
}

public/axion.css.text:
/* AXION: industrial logistics identity, independent from other ARG companies. */
:root{--ink:#202526;--muted:#586062;--yellow:#f2c431;--line:#cdd2d1;--gray:#eff1ef;--white:#fff}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{min-width:320px;margin:0;color:var(--ink);background:#fff;font-family:"Yu Gothic","Hiragino Kaku Gothic ProN",Meiryo,sans-serif;line-height:1.85}body.archive-open{overflow:hidden}button,input{font:inherit}button{cursor:pointer}a{color:inherit}a:focus-visible,button:focus-visible{outline:3px solid #ae7900;outline-offset:5px}[id]{scroll-margin-top:24px}h1,h2,h3,p,dd,td{overflow-wrap:anywhere}.skip-link{position:fixed;top:8px;left:8px;z-index:2000;padding:10px 15px;color:var(--ink);background:var(--yellow);transform:translateY(-160%)}.skip-link:focus{transform:translateY(0)}
.corporate-header{color:#fff;background:var(--ink);border-top:5px solid var(--yellow)}.corporate-header-inner{display:flex;align-items:center;justify-content:space-between;gap:30px;width:min(1320px,calc(100% - 64px));min-height:102px;margin:auto}.corporate-brand{display:flex;align-items:center;gap:16px;text-decoration:none;flex-shrink:0}.corporate-mark{display:grid;place-items:center;width:50px;height:50px;color:var(--ink);background:var(--yellow);font:900 39px/1 Arial,sans-serif;font-style:italic}.corporate-brand strong{display:block;font:900 1.3rem/1.15 Arial,sans-serif;letter-spacing:.045em}.corporate-brand strong>span{display:block;margin-top:3px;font-size:.73rem;letter-spacing:.2em}.corporate-brand small{display:block;margin-top:7px;color:#c6cccc;font-size:.63rem}.corporate-nav{display:flex;flex-wrap:wrap;gap:12px 28px}.corporate-nav a{font-size:.82rem;font-weight:700;text-decoration:none}.corporate-nav a:hover{color:var(--yellow)}
.ax-hero{position:relative;min-height:570px;background:#3a3f40}.ax-hero-image{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center 56%}.ax-hero-inner{position:relative;width:min(1320px,calc(100% - 64px));min-height:570px;margin:auto;display:flex;align-items:flex-end;padding:60px 0}.ax-hero-copy{max-width:650px;padding:32px 38px 34px;border-left:7px solid var(--yellow);background:rgba(25,30,31,.96);color:#fff}.ax-kicker{margin:0 0 15px;color:var(--yellow);font:800 .75rem/1.5 Arial,sans-serif;letter-spacing:.16em}.ax-hero h1{margin:0;font-size:clamp(2.45rem,4.4vw,4rem);line-height:1.4;letter-spacing:.025em;font-weight:900}.ax-hero-copy>p:not(.ax-kicker){margin:20px 0 0;color:#d5dada;font-size:.93rem;line-height:2}.ax-hero-link{display:inline-flex;align-items:center;gap:32px;margin-top:24px;padding:10px 17px;color:var(--ink);background:var(--yellow);font-size:.85rem;font-weight:800;text-decoration:none}.ax-hero-link span{font-size:1.2rem}.ax-hero-link:hover{background:#ffda56}
.ax-assurance{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px max(32px,calc((100% - 1320px)/2));color:var(--ink);background:var(--yellow)}.ax-assurance>span{font:800 .69rem/1.7 Arial,sans-serif;letter-spacing:.09em}.ax-assurance ul{display:flex;flex-wrap:wrap;gap:12px 32px;margin:0;padding:0;list-style:none;font-size:.87rem;font-weight:800}.ax-assurance li::before{content:"/";margin-right:12px}
.corporate-section{padding:88px 0}.corporate-inner{width:min(1160px,calc(100% - 64px));margin:auto}.section-label{margin:0 0 13px;color:var(--muted);font:800 .75rem/1.5 Arial,sans-serif;letter-spacing:.12em}.corporate-section h2{margin:0;font-size:clamp(1.8rem,3vw,2.6rem);font-weight:900;line-height:1.5}.ax-section-heading{display:grid;grid-template-columns:1fr 1fr;gap:65px;align-items:end;margin-bottom:42px}.ax-section-heading>p{margin:0;color:var(--muted);font-size:.95rem;line-height:2.05}.ax-gray{background:var(--gray)}
.ax-services{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border-top:4px solid var(--ink);border-bottom:1px solid var(--line)}.ax-services article{padding:28px 26px 30px 0}.ax-services article+article{padding-left:26px;border-left:1px solid var(--line)}.ax-service-number{color:#a0a8a8;font:800 2.4rem/1 Arial,sans-serif}.ax-services h3{margin:23px 0 14px;font-size:1.1rem;line-height:1.6}.ax-services p{margin:0;color:var(--muted);font-size:.91rem}.ax-services small{display:block;margin-top:25px;color:var(--muted);font:700 .65rem/1.6 Arial,sans-serif;letter-spacing:.04em}
.ax-dark{color:#fff;background:var(--ink)}.ax-dark .section-label{color:var(--yellow)}.ax-dark .ax-section-heading>p{color:#c3cbcb}.ax-process{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;margin:0;padding:0;list-style:none;border-top:1px solid #657071;border-bottom:1px solid #657071}.ax-process li{position:relative;padding:28px 24px 28px 0}.ax-process li+li{padding-left:24px;border-left:1px solid #657071}.ax-process span{color:var(--yellow);font:800 .78rem/1.5 Arial,sans-serif;letter-spacing:.08em}.ax-process h3{margin:18px 0 12px;font-size:1.05rem}.ax-process p{margin:0;color:#c3cbcb;font-size:.89rem}.ax-safety-note{margin:30px 0 0;padding-left:18px;border-left:4px solid var(--yellow);color:#e7eaea;font-size:.93rem;line-height:2}
.ax-improvement-layout{display:grid;grid-template-columns:1fr 1.2fr;gap:54px;align-items:start}.ax-improvement-layout h3{margin:0 0 18px;font-size:1.22rem;line-height:1.7}.ax-improvement-layout>div{padding-top:26px;border-top:3px solid var(--ink)}.ax-improvement-layout p:not(.section-label){margin:16px 0 0;color:var(--muted);font-size:.92rem;line-height:2}.ax-case{padding:30px;background:#fff;border-top:7px solid var(--yellow)}.ax-case .section-label{font-size:.7rem}.ax-case .ax-case-note{padding-top:18px;border-top:1px solid var(--line);font-size:.85rem}
.ax-compact-heading{margin-bottom:30px}.news-list{margin:0;padding:0;list-style:none;border-top:3px solid var(--ink)}.news-list li{display:grid;grid-template-columns:120px 90px minmax(0,1fr);gap:24px;padding:23px 0;border-bottom:1px solid var(--line);align-items:start;font-size:.9rem}.news-list time{padding-top:3px;color:var(--muted);font:700 .82rem/1.6 Consolas,monospace}.ax-news-category{padding:3px 8px;border:1px solid var(--line);text-align:center;font-size:.72rem;font-weight:700}.ax-company-layout{display:grid;grid-template-columns:1fr 1.5fr;gap:70px}.ax-company-message{margin:25px 0 0;color:var(--muted);font-size:.93rem}.company-table{width:100%;border-collapse:collapse;border-top:3px solid var(--ink)}.company-table th,.company-table td{padding:21px 12px;border-bottom:1px solid var(--line);text-align:left;font-size:.9rem}.company-table th{width:130px;padding-left:0;font-weight:700;vertical-align:top}
.corporate-footer{color:#fff;background:var(--ink);border-top:5px solid var(--yellow)}.corporate-footer-inner{width:min(1320px,calc(100% - 64px));min-height:110px;margin:auto;display:flex;justify-content:space-between;align-items:center;gap:30px}.fiction-notice{margin:0;color:#cbd0d0;font-size:.75rem;line-height:1.9}.archive-button{flex-shrink:0;min-width:120px;padding:11px 16px;border:1px solid #919b9b;color:#fff;background:transparent;font:800 .85rem/1.6 Consolas,monospace}
.archive-overlay{position:fixed;inset:0;z-index:1000;display:grid;place-items:center;padding:20px;background:#0c1012c9;opacity:0;visibility:hidden}.archive-overlay.is-open{opacity:1;visibility:visible}.archive-dialog{width:min(560px,100%);max-height:calc(100dvh - 40px);overflow:hidden;color:var(--ink);background:var(--white);box-shadow:0 20px 60px #0006}.archive-header{display:flex;align-items:center;justify-content:space-between;padding:19px 22px;color:var(--ink);background:var(--yellow)}.archive-header h2{margin:0;font-size:1.15rem}.archive-close{width:35px;height:35px;border:1px solid #8d762f;color:var(--ink);background:transparent;font-size:1.4rem}.archive-content{max-height:calc(100dvh - 130px);overflow:auto;padding:22px}.archive-description{margin:0 0 20px;color:var(--muted);font-size:.9rem}.archive-list{max-height:370px;margin:0;padding:0;overflow:auto;list-style:none;border-top:1px solid var(--line)}.archive-entry{display:grid;grid-template-columns:50px minmax(0,1fr);gap:12px;padding:14px 9px;border-bottom:1px solid var(--line);text-decoration:none}.archive-entry.is-locked{color:#8c9696;background:var(--gray)}.archive-number{padding-top:5px;font:800 .85rem/1 Consolas,monospace}.archive-title{font-size:.88rem}.archive-tools{margin-top:20px;padding-top:18px;border-top:1px solid var(--line)}.archive-reset-button,.reset-actions button{padding:9px 13px;border:1px solid #a5adad;background:#fff;font-size:.85rem}.reset-confirm{margin-top:16px;padding:15px;border-left:4px solid var(--yellow);background:var(--gray);font-size:.87rem}.reset-confirm p{margin:0 0 12px}.reset-actions{display:flex;justify-content:flex-end;gap:10px}.reset-actions .danger{color:#fff;background:#8c3832;border-color:#8c3832}
@media(max-width:1050px){.corporate-header-inner{flex-wrap:wrap;padding:22px 0;gap:22px}.corporate-nav{gap:10px 24px}.ax-hero-copy{max-width:590px}.ax-assurance{align-items:flex-start;flex-direction:column;gap:12px}.ax-section-heading{gap:40px}.ax-services article{padding-right:20px}.ax-services article+article{padding-left:20px}.ax-process{grid-template-columns:repeat(2,minmax(0,1fr))}.ax-process li{padding:25px!important;border-left:0!important}.ax-process li:nth-child(even){border-left:1px solid #657071!important}.ax-process li:nth-child(n+3){border-top:1px solid #657071}.ax-company-layout{gap:40px}}
@media(max-width:740px){.corporate-header-inner,.ax-hero-inner,.corporate-inner,.corporate-footer-inner{width:calc(100% - 40px)}.corporate-brand strong{font-size:1.2rem}.corporate-nav{gap:10px 20px}.corporate-nav a{font-size:.78rem}.ax-hero{min-height:0}.ax-hero-image{position:static;display:block;height:280px;object-position:65% center}.ax-hero-inner{display:block;width:100%;min-height:0;padding:0}.ax-hero-copy{max-width:none;padding:28px 24px 32px;border-left:0;border-top:5px solid var(--yellow);background:var(--ink)}.ax-hero h1{font-size:clamp(2.1rem,7vw,3rem)}.ax-hero-copy>p:not(.ax-kicker){font-size:.88rem}.ax-assurance{padding:20px}.ax-assurance ul{gap:8px 18px;font-size:.8rem}.ax-assurance li::before{margin-right:6px}.corporate-section{padding:58px 0}.ax-section-heading{grid-template-columns:1fr;gap:22px;margin-bottom:30px}.ax-services{grid-template-columns:1fr}.ax-services article,.ax-services article+article{padding:25px 0;border-left:0}.ax-services article+article{border-top:1px solid var(--line)}.ax-service-number{font-size:2rem}.ax-services h3{margin-top:15px}.ax-improvement-layout,.ax-company-layout{grid-template-columns:1fr;gap:32px}.ax-case{padding:25px 22px}.news-list li{grid-template-columns:110px minmax(0,1fr);gap:10px 18px}.news-list li>span:last-child{grid-column:1/-1}.ax-news-category{justify-self:start;min-width:70px}.corporate-footer-inner{align-items:flex-start;flex-direction:column;padding:28px 0;gap:22px}.ax-compact-heading{margin-bottom:0}}
@media(max-width:430px){.corporate-brand{gap:11px}.corporate-mark{width:42px;height:46px;font-size:35px}.corporate-brand small{font-size:.59rem}.ax-hero-image{height:235px}.ax-process{grid-template-columns:1fr}.ax-process li{padding:24px 0!important;border-left:0!important}.ax-process li:nth-child(even){border-left:0!important}.ax-process li+li{border-top:1px solid #657071}.company-table th,.company-table td{display:block;width:100%;padding:13px 0}.company-table th{padding-bottom:0;border-bottom:0}.company-table td{padding-top:6px}.archive-overlay{padding:12px}.archive-content{padding:18px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}

