const pageNumberByHref={"index.html":1,"chronect.html":13,"chronect-company.html":14,"chronect-research.html":15,"chronect-services.html":16,"chronect-news.html":17,"chronect-careers.html":18,"chronect-news-20240305.html":19,"chronect-news-20241021.html":20,"chronect-news-20250401.html":21,"chronect-news-20250526.html":22,"chronect-news-20250701.html":23,"chronect-news-20250808.html":24,"chronect-news-20250924.html":25,"chronect-news-20251216.html":26,"chronect-news-20260109.html":27,"chronect-news-20260312.html":28,"chronect-news-20260418.html":29,"chronect-news-20260520.html":30,"chronect-news-20260603.html":31,"chronect-news-20260714.html":32,"business.html":33,"business-service.html":34,"business-cases.html":35,"business-safety.html":36,"business-flow.html":37,"behavior-assistance-platform.html":38,"behavior-assistance-equipment.html":39,"pre-use-orientation.html":40,"partners.html":44,"nodelink-works.html":45,"axion-logistics.html":46,"time-back.html":3,"about.html":4,"pricing.html":5,"safety.html":6,"faq.html":7,"terms.html":8,"contact.html":9,"market.html":10,"behavior-assistance.html":11,"time-back-id.html":12,"memo-timeback-review.html":2,"business-demonstration.html":41,"business-community.html":42,"business-demonstration-area.html":43,"chronect-news-20260822.html":47,"chronect-hub.html":48,"chronect-hub-session.html":49,"chronect-hub-research.html":50,"chronect-news-20240711.html":51,"chronect-news-20251105.html":52,"chronect-news-20260218.html":53,"chronect-projects.html":54,"chronect-hub-research-20240711.html":55,"chronect-hub-research-20251105.html":56,"chronect-hub-research-20260218.html":57};
const currentPage=document.body.dataset.pageArchive==='exclude'?null:{number:Number(document.body.dataset.pageNumber),title:document.body.dataset.pageTitle,href:document.body.dataset.pageHref};
const archiveButton=document.getElementById('archiveButton'),archiveOverlay=document.getElementById('archiveOverlay'),archiveClose=document.getElementById('archiveClose'),archiveList=document.getElementById('archiveList'),archiveResetButton=document.getElementById('archiveResetButton'),resetConfirm=document.getElementById('resetConfirm'),resetCancel=document.getElementById('resetCancel'),resetAccept=document.getElementById('resetAccept');
function loadArchive(){try{const saved=JSON.parse(localStorage.getItem(archiveStorageKey)||'[]');if(!Array.isArray(saved))return[];return saved.map(page=>{if(page.href==='memo-dream.html')return{...page,href:'index.html',number:1};if(page.href==='index.html'&&(Number(page.number)===3||/TIME BACK/i.test(String(page.title||''))))return{...page,href:'time-back.html',number:3};return page}).map(page=>pageNumberByHref[page.href]?{...page,number:pageNumberByHref[page.href]}:page).map(page=>archiveTitleByNumber[page.number]?{...page,title:archiveTitleByNumber[page.number]}:page)}catch(error){return[]}}
function saveArchive(pages){try{localStorage.setItem(archiveStorageKey,JSON.stringify(pages))}catch(error){return}}
function registerCurrentPage(){const pages=loadArchive();if(!currentPage)return pages;const index=pages.findIndex(page=>page.number===currentPage.number);if(index>=0)pages[index]=currentPage;else pages.push(currentPage);pages.sort((a,b)=>a.number-b.number);saveArchive(pages);return pages}
function renderArchive(){const pages=registerCurrentPage();archiveList.textContent='';for(let pageNumber=1;pageNumber<=totalPages;pageNumber+=1){const page=pages.find(saved=>saved.number===pageNumber),item=document.createElement('li'),entry=document.createElement(page?'a':'div'),number=document.createElement('span'),title=document.createElement('span');entry.className='archive-entry';number.className='archive-number';title.className='archive-title';number.textContent=String(pageNumber).padStart(2,'0');if(page){entry.href=page.href;title.textContent=page.title}else{entry.classList.add('is-locked');title.textContent='？？？'}entry.append(number,title);item.append(entry);archiveList.append(item)}}
