.selection-process{padding:105px 0 115px;border-bottom:1px solid var(--line);background:#091a24}.selection-grid{display:grid;grid-template-columns:320px 1fr;gap:95px}.selection-grid .careers-section-heading{display:block}.selection-grid .careers-section-heading>p:last-child{margin-top:22px}.selection-steps{margin:0;padding:0;border-top:1px solid #486573;list-style:none}.selection-steps li{display:grid;grid-template-columns:55px 1fr;gap:22px;padding:24px 7px;border-bottom:1px solid var(--line)}.selection-steps li>span{color:var(--cyan);font:700 .64rem/1.7 Arial,sans-serif}.selection-steps h3{margin:0;color:#e5eef2;font-size:.91rem}.selection-steps p{margin:7px 0 0;color:#97acb5;font-size:.76rem;line-height:1.9}
