@media(max-width:900px){.careers-notice-grid,.careers-section-heading,.selection-grid,.application-grid{grid-template-columns:1fr;gap:42px}.careers-section-heading .content-label{grid-column:auto}.careers-document-meta{max-width:420px}.position-list dl{grid-template-columns:1fr}.selection-grid .careers-section-heading>p:last-child{margin-top:18px}}
@media(max-width:700px){.careers-notice,.careers-standards,.open-positions,.selection-process,.application-procedure{padding:65px 0}.careers-subpage-hero{background-position:58% center}.standards-list{grid-template-columns:1fr;margin-top:38px}.standards-list li{min-height:0;padding:25px 22px}.positions-heading{margin-bottom:38px}.position-list article{padding:28px 3px}.position-list h3{font-size:1rem}.position-list dl{gap:12px}.position-list dl>div{grid-template-columns:55px 1fr}.application-panel dl>div{grid-template-columns:1fr;gap:6px}.application-panel ul{padding-left:38px}}

/* News article */
.news-article-hero{position:relative;padding:65px 0 80px;overflow:hidden;border-bottom:1px solid var(--line);background:radial-gradient(circle at 82% 34%,rgba(37,185,216,.16),transparent 23%),linear-gradient(125deg,#030b10,#0a202b)}.news-article-hero::after{content:"";position:absolute;top:-150px;right:2%;width:430px;height:430px;border:1px solid rgba(105,216,238,.1);transform:rotate(37deg)}.news-article-hero .subpage-inner{position:relative;z-index:1}.news-article-meta{display:flex;align-items:center;gap:22px;margin:75px 0 20px}.news-article-meta time{color:#9bb0b9;font:400 .75rem/1 Arial,sans-serif;letter-spacing:.08em}.news-article-meta span{min-width:92px;padding:5px 10px;border:1px solid #315362;color:var(--cyan);font-size:.63rem;text-align:center}.news-article-hero h1{max-width:950px;margin:0;color:#edf5f7;font-size:clamp(2rem,4.3vw,3.8rem);font-weight:300;line-height:1.5;letter-spacing:.03em}
.news-article-body{padding:90px 0 115px;background:#07131b}.news-article-grid{display:grid;grid-template-columns:250px 1fr;gap:95px}.news-article-grid>aside{align-self:start;border-top:2px solid var(--cyan);border-bottom:1px solid var(--line);background:#091a24}.news-article-grid>aside>p{margin:0;padding:17px 19px;border-bottom:1px solid var(--line);color:#dce8ec;font:700 .65rem/1 Arial,sans-serif;letter-spacing:.13em}.news-article-grid>aside dl{margin:0;padding:8px 19px 14px}.news-article-grid>aside dl>div{display:grid;grid-template-columns:57px 1fr;gap:10px;padding:9px 0;border-bottom:1px solid rgba(125,166,182,.13)}.news-article-grid>aside dl>div:last-child{border-bottom:0}.news-article-grid>aside dt{color:#718d99;font-size:.62rem}.news-article-grid>aside dd{margin:0;color:#c8d6dc;font-size:.65rem}.news-article-copy{max-width:760px}.news-article-copy>p{margin:0 0 24px;color:#bdccd2;font-size:.9rem;line-height:2.2}.news-article-copy>p:first-child{color:#e0e9ec;font-size:1rem}.news-article-links{display:flex;flex-wrap:wrap;gap:12px;margin-top:50px;padding-top:25px;border-top:1px solid var(--line)}.news-article-links a{padding:10px 15px;border:1px solid #3b5d6a;color:#dbe7eb;font-size:.71rem;text-decoration:none}.news-article-links a:hover,.news-article-links a:focus-visible{border-color:var(--cyan);color:var(--cyan)}
@media(max-width:800px){.news-article-grid{grid-template-columns:1fr;gap:40px}.news-article-grid>aside{max-width:340px}}
@media(max-width:700px){.news-article-hero{padding:38px 0 58px}.news-article-meta{margin-top:52px}.news-article-hero h1{font-size:clamp(1.7rem,8.5vw,2.4rem)}.news-article-body{padding:65px 0 80px}.news-article-copy>p{font-size:.84rem;line-height:2.1}.news-article-copy>p:first-child{font-size:.9rem}.news-article-links{align-items:stretch;flex-direction:column}.news-article-links a{text-align:center}}

public/memo.css.text:
:root{--ink:#242828;--muted:#767d7c;--line:#e8ecea;--green:#27866d;--paper:#fff;--soft:#f7f9f8}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:30px}body{margin:0;background:var(--paper);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"Helvetica Neue","Noto Sans JP","Hiragino Kaku Gothic ProN","Yu Gothic",sans-serif;line-height:1.8;overflow-wrap:anywhere}button,a{-webkit-tap-highlight-color:transparent}a{color:inherit}button{font:inherit;cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid #63b5a0;outline-offset:4px}.skip-link{position:absolute;left:16px;top:-80px;background:#fff;padding:8px 14px;z-index:20}.skip-link:focus{top:12px}
.memo-header{height:88px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:30px;padding:0 48px}.memo-brand{text-decoration:none;letter-spacing:-2px;font-size:36px;font-weight:800;line-height:1.1}.brand-dot{color:var(--green)}.header-caption{font-size:12px;color:var(--muted);letter-spacing:.08em}
.article{max-width:700px;margin:78px auto 96px;padding:0 16px}.article-eyebrow{color:var(--muted);font-size:12px;letter-spacing:.12em;margin:0 0 18px}.article-header h1{font-size:32px;letter-spacing:.015em;line-height:1.55;margin:0 0 30px;font-weight:750}.author-line{display:flex;align-items:center;gap:12px;text-decoration:none;width:fit-content}.avatar{display:grid;place-items:center;flex-shrink:0;width:44px;height:44px;border-radius:50%;background:#edf0e5;color:#6e765a;font-family:Georgia,serif;font-size:28px;line-height:1}.author-name{display:block;font-size:13px;font-weight:600}.author-line time{display:block;font-size:11px;letter-spacing:.02em;color:var(--muted);margin-top:2px}.article-copy{margin-top:49px;font-size:16px;line-height:2.05;letter-spacing:.025em}.article-copy>p{margin:0 0 28px}.article-link{color:var(--green);text-decoration:underline;text-underline-offset:4px;text-decoration-thickness:1px}.article-link:hover{color:#175d4a}.article-divider{border:0;width:36px;border-top:1px solid #ced6d1;margin:48px auto}.article-copy blockquote{margin:30px 0;padding:6px 0 6px 22px;border-left:3px solid #dce3df;color:#555e59}.article-copy blockquote p{margin:0}.article-tags{display:flex;flex-wrap:wrap;gap:8px;margin:40px 0 32px}.article-tags span{font-size:12px;background:var(--soft);border-radius:4px;padding:4px 10px;color:#59605d}.author-card{display:flex;align-items:flex-start;gap:18px;border-top:1px solid var(--line);padding:30px 0}.avatar-large{width:58px;height:58px;font-size:34px}.author-card h2{font-size:15px;margin:0 0 8px}.author-card p{font-size:13px;line-height:1.9;color:#737a76;margin:0}
.memo-footer{background:var(--soft);border-top:1px solid var(--line);padding:32px 40px}.footer-main{max-width:1120px;margin:auto;display:flex;align-items:center;gap:28px}.memo-footer .memo-brand{font-size:27px;letter-spacing:-1.5px}.fiction-notice{font-size:12px;color:var(--muted);line-height:1.9;max-width:720px;margin:0}

/* TIME BACKと同じ一列リスト・濃緑のヘッダーを使用するアーカイブ */
.archive-overlay{--ink:#153b38;--muted:#607774;--green:#087f72;--line:#d8e7e3;--navy:#102e2c}
body.archive-open{overflow:hidden}
.archive-button{flex:0 0 auto;margin-left:auto;min-width:122px;padding:10px 14px;border:1px solid #64817e;border-radius:7px;color:#153b38;background:transparent;font-size:.76rem;font-weight:800;letter-spacing:.12em;cursor:pointer;min-height:44px}
.archive-button:hover,.archive-button:focus-visible{border-color:#087f72;color:#087f72}
.archive-overlay{position:fixed;inset:0;z-index:1000;display:grid;place-items:center;padding:20px;background:rgba(7,25,23,.72);opacity:0;visibility:hidden;transition:opacity .18s ease,visibility .18s ease}
.archive-overlay.is-open{opacity:1;visibility:visible}
.archive-dialog{width:min(540px,100%);max-height:min(700px,calc(100vh - 40px));overflow:hidden;border:1px solid #a9beb9;border-radius:12px;color:var(--ink);background:#f8fbfa;box-shadow:0 25px 70px rgba(0,0,0,.36);transform:translateY(10px);transition:transform .18s ease}
.archive-overlay.is-open .archive-dialog{transform:translateY(0)}
.archive-header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:18px 20px;color:#fff;background:var(--navy)}
.archive-header h2{margin:0;font-size:1.05rem;letter-spacing:.08em}
.archive-close{width:35px;height:35px;padding:0;border:1px solid #68817f;border-radius:50%;color:#fff;background:transparent;font-size:1.3rem;line-height:1;cursor:pointer}
.archive-content{max-height:calc(100vh - 120px);overflow:auto;padding:20px}
.archive-description{margin:0 0 15px;color:var(--muted);font-size:.79rem;line-height:1.7}
.archive-list{display:block;max-height:390px;margin:0;padding:0;overflow-y:auto;border-top:1px solid var(--line);list-style:none}
.archive-entry{display:grid;grid-template-columns:58px 1fr;align-items:center;gap:12px;padding:12px 11px;border-bottom:1px solid var(--line);color:var(--ink);background:#fff;text-decoration:none}
a.archive-entry:hover,a.archive-entry:focus-visible{background:#edfaf7}
.archive-entry.is-locked{color:#94a29f;background:#f1f5f4;cursor:default;user-select:none}
.archive-number{color:var(--green);font:800 .77rem/1 Consolas,monospace}
.archive-entry.is-locked .archive-number{color:#94a29f}
.archive-title{font-size:.86rem}
.archive-entry.is-locked .archive-title{letter-spacing:.16em}
.archive-tools{margin-top:16px;padding-top:14px;border-top:1px solid var(--line)}
.archive-reset-button,.reset-actions button{padding:8px 12px;border:1px solid #9aafaa;border-radius:6px;color:var(--ink);background:#fff;font-size:.76rem;cursor:pointer}
.archive-reset-button{color:#805152;border-color:#c6a9aa}
.reset-confirm{margin-top:13px;padding:14px;border-radius:8px;color:#586966;background:#eaf3f1;font-size:.79rem}
.reset-confirm p{margin:0 0 11px}
.reset-actions{display:flex;justify-content:flex-end;gap:8px}
.reset-actions .danger{color:#fff;border-color:#97595b;background:#97595b}
@media(max-width:760px){.memo-header{height:70px;padding:0 22px;gap:20px}.memo-brand{font-size:31px}.header-caption{display:none}.article{margin:46px auto 64px;padding:0 24px}.article-header h1{font-size:27px;line-height:1.55;margin-bottom:25px}.article-copy{font-size:16px;line-height:2;margin-top:36px;letter-spacing:.01em}.article-copy>p{margin-bottom:25px}.article-copy blockquote{padding-left:17px}.memo-footer{padding:25px 24px}.footer-main{flex-wrap:wrap;gap:16px}.fiction-notice{order:3;width:100%}.archive-button{min-width:95px;padding-inline:9px}.author-card{gap:14px}.article-tags{gap:6px}}
.related-articles{border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:24px 0}.related-articles h2{font-size:16px;margin:0 0 22px}.related-article{display:grid;grid-template-columns:minmax(0,1fr) 144px;align-items:start;gap:24px;text-decoration:none;padding:0 0 6px}.related-article-copy{min-width:0}.related-article-copy strong{display:block;font-size:16px;line-height:1.7}.related-article-copy>span{display:block;font-size:12px;color:var(--muted);margin-top:12px}.related-article-thumbnail{display:block;width:144px;height:80px;border-radius:8px;object-fit:contain;background:var(--soft)}.related-article:hover strong{color:var(--green)}
@media(max-width:600px){.related-article{grid-template-columns:minmax(0,1fr) 96px;gap:14px}.related-article-thumbnail{width:96px;height:64px}.related-article-copy strong{font-size:15px}}
.article-section-title{margin:42px 0 22px;font-size:21px;line-height:1.6}.receipt-figure{margin:32px 0;text-align:center}.receipt-image-link{display:block;width:min(100%,340px);margin:0 auto;cursor:zoom-in}.receipt-image-link>img{display:block;width:100%;height:auto;border:1px solid var(--line);border-radius:18px}.receipt-figure figcaption{margin-top:12px;color:var(--muted);font-size:12px}.dream-thumbnail{display:grid;place-items:center;background:#edf0e5;color:#6e765a;font-size:13px;letter-spacing:.06em}
.link-card{display:grid;grid-template-columns:minmax(0,1fr) 160px;gap:18px 24px;margin:32px 0;padding:24px;border:1px solid #dce0de;border-radius:10px;color:var(--ink);background:#fff;text-decoration:none;letter-spacing:normal;transition:background .15s ease}
.link-card:hover{background:#fafcfb}.link-card-copy{min-width:0}.link-card-title{display:block;font-size:18px;line-height:1.65;font-weight:700}.link-card-description{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden;margin-top:10px;color:var(--muted);font-size:13px;line-height:1.8}.link-card-thumbnail{align-self:start;border-radius:6px;overflow:hidden;background:#fff}.link-card-thumbnail img{display:block;width:100%;height:112px;object-fit:contain}.link-card-source{grid-column:1/-1;display:flex;align-items:center;gap:9px;font-size:12px;line-height:1.5;color:var(--muted)}.link-card-source>img{object-fit:contain;border:1px solid var(--line);border-radius:4px}.link-card-arrow{margin-left:auto;font-size:16px}
@media(max-width:600px){.link-card{grid-template-columns:minmax(0,1fr) 90px;gap:15px 12px;padding:17px;margin:28px 0}.link-card-title{font-size:15px;line-height:1.6}.link-card-description{font-size:12px;-webkit-line-clamp:3}.link-card-thumbnail img{height:90px}.link-card-source{font-size:11px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.archive-overlay,.archive-dialog,.link-card{transition:none}}

public/nodelink.css.text:
/* Independent NODELINK brand; no TIME BACK/partner stylesheet dependency. */
:root{--paper:#f7f3eb;--white:#fffdf9;--ink:#292925;--muted:#625e56;--brand:#9a4935;--line:#d9d1c4;--dark:#33332e}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{min-width:320px;margin:0;background:var(--paper);color:var(--ink);font-family:"Yu Gothic","Hiragino Kaku Gothic ProN",Meiryo,sans-serif;line-height:1.9}body.archive-open{overflow:hidden}a{color:inherit}button,input{font:inherit}button{cursor:pointer}[id]{scroll-margin-top:28px}a:focus-visible,button:focus-visible{outline:3px solid var(--brand);outline-offset:5px}img{max-width:100%}h1,h2,h3,p{overflow-wrap:anywhere}
.skip-link{position:fixed;top:8px;left:8px;z-index:2000;padding:8px 15px;color:var(--white);background:var(--ink);transform:translateY(-160%)}.skip-link:focus{transform:translateY(0)}
.corporate-header{background:var(--paper)}.corporate-header-inner{width:min(1280px,calc(100% - 80px));min-height:112px;margin:auto;display:flex;align-items:center;justify-content:space-between;gap:30px;border-bottom:1px solid var(--line)}
.corporate-brand{display:flex;align-items:center;gap:13px;text-decoration:none;flex-shrink:0}.corporate-mark{position:relative;display:block;width:43px;height:48px;color:var(--brand);font:700 32px/1.1 Georgia,serif}.corporate-mark>span{display:block;position:absolute;top:20px;left:13px;font-size:28px}.corporate-brand strong{display:block;font:600 .96rem/1.4 Georgia,serif;letter-spacing:.06em}.corporate-brand small{display:block;margin-top:6px;color:var(--muted);font-size:.66rem;letter-spacing:.06em}
.corporate-nav{display:flex;flex-wrap:wrap;gap:12px 26px}.corporate-nav a{color:var(--ink);font-size:.8rem;text-decoration:none}.corporate-nav a:hover{text-decoration:underline;text-decoration-color:var(--brand);text-underline-offset:8px}
.corporate-hero{background:var(--paper)}.corporate-hero-inner{width:min(1280px,calc(100% - 80px));margin:auto;padding:62px 0 45px;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.08fr);gap:50px;align-items:center}.hero-copy small{font:600 .69rem/1.6 Georgia,serif;color:var(--brand);letter-spacing:.17em}.hero-copy h1{margin:26px 0 0;font-family:"Yu Mincho","Hiragino Mincho ProN",serif;font-size:clamp(2.4rem,3.7vw,3.6rem);font-weight:500;line-height:1.6;letter-spacing:.025em}.hero-copy p{margin:24px 0 0;color:var(--muted);font-size:.92rem;line-height:2.1}
.nl-hero-link{display:inline-flex;align-items:center;gap:30px;margin-top:27px;padding:6px 0;border-bottom:1px solid var(--ink);font-size:.82rem;text-decoration:none}.nl-hero-link span{color:var(--brand);font-size:1.25rem}.nl-hero-link:hover{color:var(--brand)}.nl-hero-photo{margin:0;align-self:stretch;display:flex;flex-direction:column;justify-content:center}.nl-hero-photo img{display:block;width:100%;height:470px;object-fit:cover;object-position:50% 50%}.nl-hero-photo figcaption{align-self:flex-end;margin-top:14px;color:var(--muted);font-size:.72rem;letter-spacing:.1em}.nl-hero-bottom{display:flex;justify-content:space-between;gap:18px;width:min(1280px,calc(100% - 80px));margin:0 auto;padding:19px 0;border-top:1px solid var(--line);color:var(--muted);font-size:.72rem;letter-spacing:.08em}
.corporate-section{padding:92px 0;border-bottom:1px solid var(--line)}.corporate-inner{width:min(1120px,calc(100% - 80px));margin:auto}.corporate-section.tint{background:#eee8dd}.section-label{margin:0 0 14px;color:var(--brand);font:600 .72rem/1.5 Georgia,serif;letter-spacing:.16em}.corporate-section h2{margin:0;font-family:"Yu Mincho","Hiragino Mincho ProN",serif;font-size:clamp(1.65rem,2.5vw,2.4rem);font-weight:500;line-height:1.7}.section-lead{max-width:750px;margin:22px 0 0;color:var(--muted);font-size:.94rem;line-height:2.1}
.nl-philosophy{padding:110px 0;background:var(--white)}.nl-philosophy-layout{display:grid;grid-template-columns:1fr 1.1fr;gap:80px}.nl-philosophy-copy p{margin:0 0 22px;color:var(--muted);font-size:.95rem;line-height:2.15}.nl-principles{margin:32px 0 0;padding:0;list-style:none;border-top:1px solid var(--line)}.nl-principles li{padding:13px 0;border-bottom:1px solid var(--line);font-size:.9rem}.nl-principles li::before{content:"—";margin-right:14px;color:var(--brand)}
.service-cards{margin-top:40px;border-top:1px solid var(--line)}.service-card{display:grid;grid-template-columns:165px 260px minmax(0,1fr);gap:25px;padding:32px 0;border-bottom:1px solid var(--line);align-items:start}.service-card small{padding-top:5px;color:var(--brand);font:600 .68rem/1.6 Georgia,serif;letter-spacing:.06em}.service-card h3{margin:0;font-size:1.12rem;font-weight:600}.service-card p{margin:0;color:var(--muted);font-size:.9rem}
.nl-training-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:26px;margin:38px 0 0;padding:0;list-style:none}.nl-training-steps li{padding-top:18px;border-top:1px solid var(--brand)}.nl-training-steps span{color:var(--brand);font:400 1.7rem/1.3 Georgia,serif}.nl-training-steps h3{margin:17px 0 12px;font-size:.96rem;font-weight:600}.nl-training-steps p{margin:0;color:var(--muted);font-size:.85rem}
.nl-timeback{margin-top:48px;padding:32px 36px;background:var(--white);border-left:3px solid var(--brand)}.nl-timeback h3{margin:10px 0 20px;font-family:"Yu Mincho","Hiragino Mincho ProN",serif;font-size:1.25rem;font-weight:500}.nl-timeback p:not(.section-label){max-width:850px;margin:14px 0 0;color:var(--muted);font-size:.9rem;line-height:2}
