    localStorage:{getItem(){return saved;},setItem(key,value){assert.equal(key,'timeback-page-archive-v1');saved=value;writes++;}}});
  return {context,nodes,getSaved:()=>JSON.parse(saved),getWrites:()=>writes};
}

